&lt;table width=&quot;80px&quot;&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td&gt;&lt;abbr title=&quot;Cette option est plus sp&#233;cifique, voire r&#233;serv&#233;e, aux membres de la race indiqu&#233;e. Discutez avec votre MJ de sa disponibilit&#233; pour votre personnage.&quot;&gt;&lt;a href=&quot;./Pathfinder-RPG.Humain.ashx&quot;&gt;&lt;img src=&quot;/wiki/public/upload/Illustrations/PNJ/Humain.jpg&quot; width=&quot;80%&quot; style=&quot;float:center; margin: 0px -50px 0px 7px; border: 1px solid #4b3124&quot;&gt;&lt;/a&gt;&lt;/abbr&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td&gt;&lt;div style=&quot;text-align:center; font-size: 81%; font-weight: bold;&quot;&gt;Option plus&lt;br /&gt;commune chez&lt;br /&gt;les &lt;a class=&quot;pagelink&quot; href=&quot;../Golarion/Kellides.html&quot; title=&quot;Les Kellides&quot;&gt;kellides&lt;/a&gt;.&lt;/div&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Lame du v&#233;ritable guerrier&lt;div style=&quot;float:right;&quot;&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Races de la mer Int&#233;rieure (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Inner Sea Races/Races de la mer Int&#233;rieure&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoISR.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;b&gt;Aura&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Enchantement.html&quot; title=&quot;Enchantement&quot;&gt;Enchantement&lt;/a&gt; mod&#233;r&#233;e ; &lt;b&gt;NLS&lt;/b&gt; 9 ; &lt;b&gt;Emplacement&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Armes-Magiques-Sp&#233;cifiques.html&quot; title=&quot;Armes magiques sp&#233;cifiques&quot;&gt;aucun (arme)&lt;/a&gt; ; &lt;b&gt;Prix&lt;/b&gt; 50.350 po ; &lt;b&gt;Poids&lt;/b&gt; 4 kg
&lt;div class=&quot;box&quot;&gt;Description&lt;/div&gt;
Cette &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;p&#233;e-&#192;-Deux-Mains-(Arme).html&quot; title=&quot;&#201;p&#233;e &#224; deux mains&quot;&gt;&#233;p&#233;e &#224; deux mains&lt;/a&gt; +3&lt;/i&gt; semble avoir &#233;t&#233; forg&#233;e grossi&#232;rement et des inscriptions en hallit sont grav&#233;es sur sa garde. Le porteur gagne en puissance contre les lanceurs de sorts, comme les &lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re.html&quot; title=&quot;La sorci&#232;re&quot;&gt;sorci&#232;res&lt;/a&gt;. La lame est consid&#233;r&#233;e comme une arme &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Tueuse.html&quot; title=&quot;tueuse (propri&#233;t&#233;)&quot;&gt;tueuse&lt;/a&gt;&lt;/i&gt; contre toute cr&#233;ature qui a la capacit&#233; de lancer des &lt;a class=&quot;pagelink&quot; href=&quot;Magie-Profane.html&quot; title=&quot;La magie profane&quot;&gt;sorts profanes&lt;/a&gt; (les &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Magiques-(Capacit&#233;).html&quot; title=&quot;Pouvoirs magiques (Mag)&quot;&gt;pouvoirs magiques&lt;/a&gt; ne comptent pas, mais la capacit&#233; d&#39;un &lt;a class=&quot;pagelink&quot; href=&quot;Type-Dragon.html&quot; title=&quot;Dragon&quot;&gt;dragon&lt;/a&gt; &#224; lancer des sorts d&#39;ensorceleur compte, par exemple).
&lt;div class=&quot;box&quot;&gt;Cr&#233;ation&lt;/div&gt;
&lt;b&gt;Conditions&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-Darmes-Et-Armures-Magiques.html&quot; title=&quot;Cr&#233;ation d&amp;#39;armes et armures magiques&quot;&gt;Cr&#233;ation d&#39;armes et armures magiques&lt;/a&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Zone-Dantimagie.html&quot; title=&quot;Zone d&amp;#39;antimagie&quot;&gt;zone d&#39;antimagie&lt;/a&gt;&lt;/i&gt;, le cr&#233;ateur doit &#234;tre kellide ; &lt;b&gt;Co&#251;t&lt;/b&gt; 25.350 po
&lt;/div&gt;
